import{POINTS,EDGES,coords,initial,count,moves,segment,finish,turns}from'./engine.js';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
let state=initial(),history=[],selected=null,chain=false,busy=false,mode='ai',human='geese',level='medium',highlights=true,sound=false,token=0,worker=null,pendingReset=null,audio=null,last=null,blocked=false;
const pieceEls=new Map(),pointEls=new Map();const csspos=p=>{const{x,y}=coords(p);return{left:`${(80+x*90)/7}%`,top:`${(80+y*90)/7}%`}};
for(const[a,b]of EDGES){const p=coords(a),q=coords(b);$('#lines').insertAdjacentHTML('beforeend',`<line class="board-line" x1="${80+p.x*90}" y1="${80+p.y*90}" x2="${80+q.x*90}" y2="${80+q.y*90}"/>`);}
for(const p of POINTS){const el=document.createElement('button');el.className='point';Object.assign(el.style,csspos(p));el.dataset.point=p;el.setAttribute('aria-label',`Empty point ${String.fromCharCode(65+p%7)}${Math.floor(p/7)+1}`);el.onclick=()=>clickPoint(p);$('#points').append(el);pointEls.set(p,el);}
function makePiece(id,type){const el=document.createElement('button');el.className=`piece ${type}`;el.dataset.piece=id;el.onclick=()=>clickPiece(id);$('#pieces').append(el);pieceEls.set(id,el);return el;}
makePiece('fox','fox');for(let i=0;i<13;i++)makePiece(`g${i}`,'goose');
const pos=id=>id==='fox'?state.fox:state.geese[Number(id.slice(1))];
const isHuman=()=>mode==='local'||state.side===human;
function snapshot(){return{state:structuredClone(state),last:structuredClone(last)}}
function playSound(capture=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(capture?230:480,t);o.frequency.exponentialRampToValueAtTime(capture?65:160,t+.12);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.09,t+.005);g.gain.exponentialRampToValueAtTime(.0001,t+.18);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.2);}catch{}}
function render(){
 const mine=isHuman()&&!busy&&!state.winner;const legal=selected!==null?moves(state,selected,chain):[];
 for(const[p,el]of pointEls){const m=legal.find(m=>m.to===p);el.className='point'+(m&&highlights?' legal'+(m.capture!==null?' capture':''):'')+(last?.from===p?' last':'');el.disabled=!mine;el.setAttribute('aria-label',`${String.fromCharCode(65+p%7)}${Math.floor(p/7)+1}${m?', legal '+(m.capture!==null?'capture':'move'):''}`);}
 for(const[id,el]of pieceEls){const p=pos(id);if(p<0){el.classList.add('captured');el.disabled=true;el.setAttribute('aria-hidden','true');continue;}el.removeAttribute('aria-hidden');Object.assign(el.style,csspos(p));const owned=(state.side==='fox')===(id==='fox');el.className=`piece ${id==='fox'?'fox':'goose'}${selected===p?' selected':''}${mine&&owned?' selectable':''}`;el.disabled=!mine||!owned||chain&&id!=='fox';el.setAttribute('aria-label',`${id==='fox'?'Fox':'Goose'} at ${String.fromCharCode(65+p%7)}${Math.floor(p/7)+1}`);el.setAttribute('aria-pressed',String(selected===p));}
 $('#turn-number').textContent=String(state.turn).padStart(2,'0');$('#geese-count').textContent=count(state);$('#capture-track').innerHTML=Array.from({length:8},(_,i)=>`<i class="${i<13-count(state)?'filled':''}"></i>`).join('');$('#capture-track').ariaLabel=`${13-count(state)} of 8 geese captured`;
 $('#match-label').textContent=mode==='local'?'LOCAL TWO-PLAYER':'YOU & THE COMPUTER';$('#board-turn').textContent=state.winner?`${state.winner.toUpperCase()} WIN`:chain?'CONTINUE OR END TURN':`${state.side.toUpperCase()} TO MOVE`;
 $('#turn-label').textContent=state.winner?'GAME COMPLETE':blocked?'NO LEGAL GOOSE MOVES':busy?'THE COMPUTER IS THINKING':mode==='local'?`${state.side.toUpperCase()}’S TURN`:isHuman()?'YOUR TURN':'COMPUTER’S TURN';
 $('#turn-title').textContent=state.winner?state.winner==='fox'?'The fox prevails.':'The flock holds.':blocked?'The flock cannot move.':chain?'The hunt continues.':busy?(state.side==='fox'?'A fox makes its plans.':'The flock is closing in.'):state.side==='fox'?'Find your opening.':'Gather the flock.';
 $('#turn-hint').textContent=state.winner?state.winner==='fox'?'Only five geese remain. A cunning escape.':'No step. No jump. The fox is surrounded.':blocked?'No forward or sideways move is available. Undo or restart to continue.':chain?'Jump again, or end your turn. The choice is yours.':busy?'Considering the next move…':state.side==='fox'?'Choose the fox, then a glowing point. Amber rings mark captures.':'Choose a goose, then a glowing point. The flock moves toward the top.';
 $('#side-objective').innerHTML=mode==='local'?'<strong>Two different goals</strong> Geese: trap the fox. Fox: capture eight geese.':human==='geese'?'<strong>Your goal</strong> Close every escape. Win when the fox cannot move or jump.':'<strong>Your goal</strong> Capture eight geese. You win the instant only five remain.';
 if(!busy&&!state.winner&&!blocked&&!chain&&selected!==null)$('#turn-hint').textContent=legal.length?`Now choose ${highlights?'a glowing':'an empty connected'} point.${state.side==='fox'?' Amber rings are jumps; captures are optional.':' Move one step toward the top or sideways—never backward.'}`:'This piece has no legal move. Choose another goose.';
 $('#undo').title=mode==='local'?'Take back the previous turn':'Take back your turn and the computer’s reply';
 $('#end-turn').hidden=!chain||busy||!!state.winner;$('#undo').disabled=!history.length||(mode==='ai'&&!history.some(h=>h.state.side===human));$('#difficulty').disabled=busy;$('#side-settings').hidden=mode==='local';
 all('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));all('[data-side]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.side===human)));
}
function clickPiece(id){if(busy||state.winner||!isHuman())return;const p=pos(id);if(p<0||(state.side==='fox')!==(id==='fox'))return;if(chain&&id!=='fox')return;selected=selected===p&&!chain?null:p;render();}
function clickPoint(p){if(busy||state.winner||!isHuman()||selected===null)return;const m=moves(state,selected,chain).find(m=>m.to===p);if(!m)return;if(!chain)history.push(snapshot());doSegment(m);if(state.winner){showWinner();return;}if(m.capture!==null&&moves(state,state.fox,true).length){chain=true;selected=state.fox;render();}else endTurn();}
function doSegment(m){state=segment(state,m);last=m;playSound(m.capture!==null);if(m.capture!==null){const flash=document.createElement('span');flash.className='capture-flash';Object.assign(flash.style,csspos(m.capture));$('#effects').append(flash);setTimeout(()=>flash.remove(),600);}render();}
function endTurn(){chain=false;selected=null;if(!state.winner)state=finish(state);render();if(state.winner)showWinner();else scheduleAI();}
function showWinner(){busy=false;chain=false;selected=null;render();$('#win-title').textContent=state.winner==='fox'?'Cunning wins.':'Together, victorious.';$('#win-description').textContent=state.winner==='fox'?'Eight captures. Five geese left. The fox has broken the flock.':'The last opening is closed. The fox has no legal move or capture.';$('#win-overlay').hidden=false;}
function scheduleAI(){blocked=state.side==='geese'&&!turns(state).length;if(blocked){render();return;}if(mode!=='ai'||isHuman()||state.winner)return;busy=true;render();const request=++token;worker?.terminate();worker=new Worker('./ai-worker.js',{type:'module'});worker.onmessage=async({data})=>{if(data.token!==token)return;const path=data.path;if(!path){busy=false;blocked=true;render();return;}history.push(snapshot());await new Promise(r=>setTimeout(r,450));for(const m of path){if(request!==token)return;doSegment(m);await new Promise(r=>setTimeout(r,370));}if(request!==token)return;busy=false;if(state.winner)showWinner();else endTurn();};worker.onerror=()=>{if(request!==token)return;busy=false;$('#turn-label').textContent='COMPUTER UNAVAILABLE';$('#turn-hint').textContent='Choose two players or restart to try again.';};worker.postMessage({state,level,token:request});}
function reset(){token++;worker?.terminate();worker=null;state=initial();history=[];chain=false;busy=false;selected=null;last=null;blocked=false;$('#win-overlay').hidden=true;render();scheduleAI();}
function requestReset(fn,title='Start again?'){if(history.length||chain){pendingReset=fn;$('#confirm-title').textContent=title;$('#confirm').showModal();}else fn();}
$('#undo').onclick=()=>{if(!history.length)return;token++;worker?.terminate();let index=history.length-1;if(mode==='ai'){const found=history.findLastIndex(h=>h.state.side===human);if(found>=0)index=found;else return;}const h=history[index];state=structuredClone(h.state);last=h.last;history=history.slice(0,index);selected=null;chain=false;busy=false;blocked=false;$('#win-overlay').hidden=true;render();};
$('#restart').onclick=()=>requestReset(reset);$('#play-again').onclick=reset;$('#review-board').onclick=()=>$('#win-overlay').hidden=true;$('#end-turn').onclick=()=>{if(chain&&!busy)endTurn();};
all('[data-mode]').forEach(b=>b.onclick=()=>{if(mode!==b.dataset.mode)requestReset(()=>{mode=b.dataset.mode;reset();},'Change the table?');});all('[data-side]').forEach(b=>b.onclick=()=>{if(human!==b.dataset.side)requestReset(()=>{human=b.dataset.side;reset();},'Change sides?');});
$('#difficulty').onchange=e=>{level=e.target.value;if(busy){token++;worker?.terminate();busy=false;scheduleAI();}};
$('#hints').onclick=()=>{highlights=!highlights;$('#hints').classList.toggle('active',highlights);$('#hints').setAttribute('aria-pressed',String(highlights));render();};$('#sound').onclick=()=>{sound=!sound;$('#sound').classList.toggle('active',sound);$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').title=sound?'Sound on':'Sound off';if(sound)playSound();};
$('.close-dialog').onclick=()=>$('#rules').close();$('.close-rules').onclick=()=>$('#rules').close();$('#cancel-reset').onclick=()=>{$('#confirm').close();pendingReset=null;};$('#confirm-reset').onclick=()=>{$('#confirm').close();pendingReset?.();pendingReset=null;};
for(const d of all('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
const readGame=()=>({side:state.side,fox:state.fox,geese:state.geese.filter(p=>p>=0),winner:state.winner,turn:state.turn,thinking:busy,continuingCapture:chain,legalMoves:state.winner?[]:chain?moves(state,state.fox,true):state.side==='fox'?moves(state,state.fox):state.geese.filter(p=>p>=0).flatMap(p=>moves(state,p))});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();for(const tool of[{name:'read_fox_and_geese_game',description:'Read current game and legal moves. Points are row * 7 + column, with zero-based row and column.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>readGame()},{name:'move_fox_and_geese_piece',description:'Make one legal human move. A capture chain may remain open; end it using end_fox_capture_turn.',inputSchema:{type:'object',properties:{from:{type:'integer'},to:{type:'integer'}},required:['from','to'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(busy||!isHuman()||state.winner||!Number.isInteger(input.from)||!Number.isInteger(input.to))throw Error('A human move is not available.');if(chain&&input.from!==state.fox||!chain&&(state.side==='fox'?input.from!==state.fox:!state.geese.includes(input.from)))throw Error('Wrong piece.');const m=moves(state,input.from,chain).find(m=>m.to===input.to);if(!m)throw Error('Illegal move.');selected=input.from;clickPoint(input.to);return readGame();}},{name:'end_fox_capture_turn',description:'End an optional human fox capture chain.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async()=>{if(!chain||busy||!isHuman())throw Error('No human capture chain.');endTurn();return readGame();}}])try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();
